      {% if acceptanceid == blank %}
        <div class="err" style="display:block;">Missing acceptanceid query param.</div>
      {% else %}
        <div class="row"><div class="label">Acceptance Name</div><div class="val" id="accName">—</div></div>
        <div class="row"><div class="label">Acceptance Status</div><div class="val" id="accStatus">—</div></div>
        <div class="row"><div class="label">Email</div><div class="val" id="accEmail">—</div></div>
        <div class="row"><div class="label">Amount</div><div class="val" id="accAmt">—</div></div>
        <div class="row"><div class="label">Offering</div><div class="val" id="offName">—</div></div>

