                throw new Error("HTTP " + res.status + "\\n" + (text || ""));
              }
              return JSON.parse(text);
            })
            .then(data => {
              // Optional token validation (only if you want it)
              if(token && data.hit_clienttoken && token !== data.hit_clienttoken){
                showErr("Token mismatch. URL token does not match record hit_clienttoken.");
              }

              document.getElementById("accName").textContent = data.hit_name || "—";

              // Choice fields often come through as numbers here
              document.getElementById("accStatus").textContent =
                (data.hit_acceptancestatus !== undefined && data.hit_acceptancestatus !== null)
                  ? String(data.hit_acceptancestatus)
                  : "—";

              document.getElementById("accEmail").textContent = data.hit_email || "—";

              const amt = (data.hit_totalamount && Number(data.hit_totalamount) > 0)
                ? data.hit_totalamount
                : ((Number(data.hit_baseamount)||0) + (Number(data.hit_donationaddonamount)||0));

              document.getElementById("accAmt").textContent = fmtMoney(amt);

              const off = data.hit_Offering;
